-- UK DASS Alpha 1.2.0, Stage 6: authoritative geometry for EGD397A/B from UK AIP SUP 077/2026

create or replace function public.admin_apply_tda_supplement_077(p_import_run_id uuid)
returns void language plpgsql security definer set search_path='' as $function$
declare v_user uuid:=auth.uid();v_count int;v_polygon jsonb:='[[53.1043646,-0.4312605],[53.1008985,-0.4207771],[53.096902,-0.4108323],[53.0924048,-0.4015001],[53.0874407,-0.3928503],[53.0820467,-0.3849471],[53.0762632,-0.3778494],[53.0701333,-0.3716099],[53.0637028,-0.3662748],[53.0570197,-0.3618834],[53.0501339,-0.3584682],[53.0430968,-0.356054],[53.0359607,-0.3546584],[53.0287788,-0.3542913],[53.0216046,-0.3549549],[53.0144915,-0.3566438],[53.0074924,-0.3593448],[53.0006594,-0.3630375],[52.9940432,-0.3676938],[52.9876929,-0.3732789],[52.9816557,-0.3797508],[52.9759765,-0.3870611],[52.9706973,-0.3951554],[52.9658573,-0.4039732],[52.9614923,-0.413449],[52.9576348,-0.4235124],[52.9543132,-0.4340887],[52.9515523,-0.4450994],[52.9493724,-0.456463],[52.9477896,-0.4680952],[52.9468158,-0.47991],[52.9464581,-0.4918198],[52.9467191,-0.5037365],[52.9475969,-0.5155719],[52.949085,-0.5272385],[52.9511725,-0.5386497],[52.9538438,-0.5497211],[52.9570792,-0.5603706],[52.9608546,-0.5705192],[52.9651422,-0.5800917],[52.9699102,-0.5890169],[52.9751232,-0.5972285],[52.9807426,-0.6046652],[52.9867267,-0.6112716],[52.993031,-0.6169983],[52.9996088,-0.6218025],[53.0064113,-0.6256479],[53.0133878,-0.6285056],[53.0204865,-0.6303539],[53.0276546,-0.6311784],[53.0348388,-0.6309726],[53.0419856,-0.6297374],[53.0490418,-0.6274816],[53.0559547,-0.6242215],[53.0626728,-0.6199809],[53.069146,-0.614791],[53.075326,-0.6086901],[53.0811666,-0.6017233],[53.0866243,-0.5939424],[53.0916582,-0.5854053],[53.0885732,-0.5745193],[53.0862742,-0.5633667],[53.0845516,-0.5519301],[53.0834177,-0.5402919],[53.0828806,-0.5285358],[53.0829443,-0.5167463],[53.0836082,-0.5050081],[53.0848677,-0.4934057],[53.0867135,-0.4820225],[53.0891326,-0.4709404],[53.0921074,-0.4602391],[53.0956165,-0.4499958],[53.0996348,-0.4402841],[53.1041332,-0.4311743]]'::jsonb;
begin
 if v_user is null or not exists(select 1 from public.admin_profiles a where a.user_id=v_user and a.account_status='ACTIVE') then raise exception 'Active administrator required';end if;
 if not exists(select 1 from public.notam_sync_runs r where r.id=p_import_run_id and r.source_name='NATS_PIB' and r.sync_status in('STARTED','PARTIAL') and r.coverage_end>now()) then raise exception 'PIB import is not reviewable';end if;
 update public.notam_import_items set parsed_geometry=v_polygon,lower_limit=case designator when 'EGD397A' then 'SFC' else 'FL050' end,upper_limit=case designator when 'EGD397A' then 'FL050' else 'FL105' end,resolution_note='Geometry and vertical limits verified against UK AIP SUP 077/2026, published 23 July 2026. Lateral boundary comprises the published clockwise and anti-clockwise 5 NM arcs. Formal table limit FL105 used for EGD397B; page-two graphic displays FL150.',resolved_by=v_user,resolved_at=now()
 where import_run_id=p_import_run_id and designator in('EGD397A','EGD397B') and event_kind='ACTIVATION' and match_status='UNMATCHED';
 get diagnostics v_count=row_count;if v_count<>2 then raise exception 'Expected two unresolved EGD397 activation items, found %',v_count;end if;
 insert into public.admin_audit_log(admin_user_id,action_type,summary,metadata) values(v_user,'TDA_SUPPLEMENT_GEOMETRY_APPLIED','Applied UK AIP SUP 077/2026 geometry to EGD397A/B',jsonb_build_object('import_run_id',p_import_run_id,'supplement','UK AIP SUP 077/2026','publication_date','2026-07-23','effective_period','2026-07-27 to 2026-10-25','areas',jsonb_build_object('EGD397A','SFC-FL050','EGD397B','FL050-FL105'),'geometry_points',jsonb_array_length(v_polygon),'vertical_limit_discrepancy','Formal table states FL105 for EGD397B; illustration label states FL150. Formal table used.'));
end;$function$;
revoke all on function public.admin_apply_tda_supplement_077(uuid) from public,anon;
grant execute on function public.admin_apply_tda_supplement_077(uuid) to authenticated;
notify pgrst,'reload schema';
